INSERT INTO sokoeats_screen_payloads (screen_key, payload)
VALUES ('customer_service_lesson', '{"sourceFiles":["customer_service_lesson/code.html","customer_service_lesson/screen.png"],"step":"Step 4/6","module":"Module 4","title":"Customer Service Excellence","duration":"08:45","imageUrl":"https://lh3.googleusercontent.com/aida-public/AB6AXuCPnEAcRPGN81PTWWc7Q2S_9JwPp7bVMqUIRsBcQp8075Cv-0wBYv-5m_ttTsP6ys72GvP4Ch2bqU0fHNFUt0dxFVbWK_M4k9BGtlxQT2Nuk1-Zt5gxWYM37ZYFFaXb37Gj4kNy5OQhvoJneBYB5ct0l0juVRizhrg6uDLQ01RV9UpvgbZ5cYd-n6fKPhUp1f1pycQlCxemHvPOz7lEmwoOdED4ELZljnvzihDzfrCPLCGpMwU1SAKs","sections":[{"title":"The Perfect Handover","body":"First impressions matter. As the face of our service, your interaction during the handover is the most critical part of the customer''s journey."},{"title":"Greet with a Smile","body":"Always start with a friendly greeting like \"Good afternoon! Your order from [Restaurant] is here.\" Use the customer name if it is available in the app."},{"title":"Bag Management","body":"Carefully remove the order from your thermal bag in front of the customer. This demonstrates that you''ve kept their food at the correct temperature."},{"title":"Accuracy Check","body":"Briefly confirm the contents or the number of items."}],"proTip":"If an item is missing or damaged, never argue. Apologize and immediately direct the customer to the ''Help'' button in their app.","quote":"A polite farewell like ''Enjoy your meal!'' or ''Have a great evening!'' can be the difference between a 4-star and a 5-star rating."}'::jsonb)
ON CONFLICT (screen_key) DO UPDATE SET payload = EXCLUDED.payload, updated_at = NOW();

