INSERT INTO sokoeats_screen_payloads (screen_key, payload)
VALUES ('merchant_terms_conditions', '{"sourceFiles":["merchant_terms_conditions/code.html","merchant_terms_conditions/screen.png"],"title":"Terms & Conditions","subtitle":"Please review the merchant agreement carefully before continuing.","highlights":[{"title":"Commission & Payout","body":"15% platform fee. Daily settlements via M-Pesa at 4 PM EAT."},{"title":"Data & Security","body":"Your data is encrypted and used only for operational success."}],"terms":[{"title":"Commission Fees (15%)","body":"SokoEats charges a standard commission of 15% on all successful transactions processed through the platform. Fees are deducted automatically from gross sales before final payout."},{"title":"M-Pesa Payout Terms","body":"Merchant payouts are processed daily via M-Pesa to the registered merchant number. Transactions after 4:00 PM are included in the following day''s payout. A KES 22 transaction fee applies to each payout batch."},{"title":"Merchant Responsibilities","body":"Merchants are responsible for quality, accuracy, fulfillment, updated inventory, and current pricing. Reliability issues may result in temporary suspension or a 2% service penalty."},{"title":"Data Privacy","body":"Sales history, customer feedback, and financial logs are collected solely to provide platform services and growth analytics. Business data is never sold to advertisers."}],"version":"Agreement Version 2.4","updated":"Last updated: October 2023","imageUrl":"https://lh3.googleusercontent.com/aida-public/AB6AXuByECnbT5YZkz172n3PWfCeTjvoXa5TeqRhk56aSPFSAEuCheBV2rg2l1rtC2_OozjWoGrDZudal5NCl-UGnF_Jg2ek7p6sZgHZMkTkSbtgPHG-93gEhOluumTgmN7gBTKXtvRDoV54A91vL5j2cXKNs_ENbIvcJi3JORaaci5UTO5jaV5yRLiuL1qfTXX8V83_4QtdpoEmcZfDVLiLANtrj57nfbC9LKDTVWQ_67zNmuYWJ5ufJeyK"}'::jsonb)
